import React from "react";
import { Link, useNavigate } from "react-router-dom";

const Navbar = ({ role }) => {
  const navigate = useNavigate();

  return (
    <nav style={{ padding: "10px 20px", backgroundColor: "#333", color: "#fff", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
      <div style={{ display: "flex", gap: "20px" }}>
        <Link to="/" style={{ color: "#fff", textDecoration: "none" }}>Dashboard</Link>
        {role === "admin" && (
          <>
            <Link to="/logs" style={{ color: "#fff", textDecoration: "none" }}>Logs</Link>
            <Link to="/analytics" style={{ color: "#fff", textDecoration: "none" }}>Analytics</Link>
          </>
        )}
      </div>
      {role !== "admin" && (
        <button 
          onClick={() => navigate("/admin/login")}
          style={{ backgroundColor: "#4CAF50", color: "#fff", border: "none", padding: "6px 12px", borderRadius: "4px", cursor: "pointer" }}
        >
          Admin Login
        </button>
      )}
    </nav>
  );
};

export default Navbar;
